(* [comment removed for export] *)
Definition put_staticM (sp tp : word) (LB0 : list block) (P E lo B p0 R : Z) (bs : list byte) (mb : byte) : Prop :=
  put_static H MX CX sp tp LB0 P E lo B p0 R bs /\ bv_unsigned mb <= 1.

(* [comment removed for export] *)
Definition put_inv (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (m0 : mem) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (d : pst) (m : mem) (p : Z) (j8 : list byte) (tmp : list cell) (E' : ecv) : Prop :=
  mem_inv usegs m /\ stk usegs m lo (bv_unsigned sp + -144)
  /\ rw_cells usegs m (errno_addr tp) [C4 (ps_errv d)] /\ hs_rauxv_ok H m B
  /\ hs_RHEAP H (ps_st d) (ps_LBn d ++ LB0) m
  /\ put_frame m sp j8 tmp p
  /\ rw_cells usegs m (bv_unsigned sp + -104) (map C8 (put_sv s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
  /\ rw_cells usegs m P (ParserCoreCells (ps_c d) pad7 pad2)
  /\ rw_cells usegs m E (ErrCodeCells E')
  /\ rw_cells usegs m (P + 240) [C1 (ps_rdi d)] /\ HttpCat m (ps_g d) /\ (FieldTabZero m \/ FT m)
  /\ PutU P p0 bs mb d m /\ PutL sp P p0 bs LB0 L0 es0 h0 d /\ PutB LB0 p0 R MX CX d p
  /\ xpres LB0 (bv_unsigned sp) (put_X P E L0 es0) m0 m
  /\ p0 <= p <= p0 + Z.of_nat (length bs).

(* [comment removed for export] *)
Definition put_at (pc : Z) (ak : Z -> word -> word -> Prop)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (d : pst) (j8 : list byte) (tmp : list cell),
    cfg_ms cf = put_ms pc rax sp gp tp t0 t1 t2 E p0 a0 a1 a2 a3 a4 a5 a6 a7 P (wz (p0 + Z.of_nat (length bs) - p)) (p0 + Z.of_nat (length bs)) t3 t4 t5 t6 F fc m
    /\ ak (pc_state (ps_c d)) a0 a2
    /\ hs_KREL H (ps_st d) (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ put_inv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb d m p j8 tmp EC_clear.

(* [comment removed for export] *)
Definition put_mid (pc : Z) (stc : pcore -> ecv -> Prop)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p q : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (d : pst) (j8 : list byte) (tmp : list cell) (E' : ecv),
    cfg_ms cf = put_ms pc rax sp gp tp t0 t1 t2 E p0 a0 a1 a2 a3 a4 a5 a6 a7 P (wz (p0 + Z.of_nat (length bs) - p)) (p0 + Z.of_nat (length bs)) t3 t4 t5 t6 F fc m
    /\ stc (ps_c d) E'
    /\ hs_KREL H (ps_st d) (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ put_inv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb d m q j8 tmp E'
    /\ p0 <= p <= q /\ ec_ok E' /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p < q).

(* [comment removed for export] *)
Definition st11c : pcore -> ecv -> Prop := fun c E' => pc_state c = 11 -> E' = EC_clear.

(* [comment removed for export] *)
Definition ak_disp (p : Z) : Z -> word -> word -> Prop := fun st a0 a2 => a0 = wz st /\ st <> 11.   (* [comment removed for export] *)
Definition ak_st (k : Z) : Z -> word -> word -> Prop := fun st _ _ => st = k.
Definition ak_tgt (k p : Z) : Z -> word -> word -> Prop := fun st a0 a2 => st = k /\ a0 = wz (put_target k).

(* [comment removed for export] *)
Definition put_res (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config) : Prop :=
  put_post0 H MX CX ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb cf
  \/ exists p', p < p' < p0 + Z.of_nat (length bs) /\ put_at PUT_DISP (ak_disp p') ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p' cf.

