Local Ltac open_static STAT :=
  let PU := fresh "PU" in
  pose proof STAT as ((PU & RCR & RN & SPB & PB & EB & BHI & TP & MXLE & CXLE) & MBB); pose proof PU as PU0;
  destruct PU as (N1 & LO & IMG & CEIL & QLO & QHI & PLO & PHI & ELO & EHI & DPE & AL16 & EAL);
  apply uhide_i in EAL; apply uhide_i in MBB;
  unfold PUT_STACK, IPF_STACK, IPF_FRAME, OTF_STACK, INS_STACK, ROPNEW_STACK, RMALLOC_STACK in LO.

