Local Ltac cbn_ps_all := cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_st ps_errv] in *.

Lemma HB0_of : forall st LB LB0 m, hs_RHEAP H st (LB ++ LB0) m -> forall b, In b LB0 -> blk_addr b + blk_size b <= hceil.
Proof.
  intros st LB LB0 m HP b Hb. destruct (hh_blocks H HH _ _ _ b HP ltac:(apply in_or_app; right; exact Hb)) as (_ & _ & _ & X4 & _). exact X4.
Qed.

(* [comment removed for export] *)
Lemma body_res_ge : forall es insz r m b, MBuf m b es insz -> Z.of_nat (length es) <= KB -> 0 <= insz -> 0 <= r ->
  mb_cap es <= 3 * insz + 512 -> 0 <= body_res es insz r.
Proof.
  intros es insz r m b MB LES INZ R0 CAP. unfold body_res, KB in *.
  pose proof (mb_cap_ge0' es ltac:(intros x sz IN; pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN); lia)) as CAP0. lia.
Qed.
