Lemma put_call_pf : forall (pc ret st0 : Z), put_setup_stmt pc P_BP_PARSE_FIELDS ret -> (st0 = 2 \/ st0 = 10) ->
  0 <= ret < 2^64 -> ret mod 2 = 0 ->
  forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_staticM sp tp LB0 P E lo B p0 R bs mb ->
  put_at pc (ak_st st0) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
  hs_SR H (fun cf' => exists q, put_mid ret (fun c E' => pc_state c = st0)
                         ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p q cf') cf.
