(* [comment removed for export] *)
Lemma put_frame_transport : forall W m m' sp j8 tmp q,
  put_frame m sp j8 tmp q -> munch W m m' -> wmono usegs m m' -> disjoint_from W (bv_unsigned sp + -144) 40 -> put_frame m' sp j8 tmp q.
Proof.
  intros W m m' sp j8 tmp q (F8 & TMP & SZ & PP) MU WM DJ.
  assert (DJ' : forall A n, bv_unsigned sp + -144 <= A -> A + Z.of_nat n <= bv_unsigned sp + -104 -> disjoint_from W A (Z.of_nat n)).
  { intros A n H1 H2. clear - DJ H1 H2. induction W as [|[u v] W IH]; [exact I|]. cbn in DJ |- *. destruct DJ as [D1 D2]. split; [lia | apply IH; exact D2]. }
  unfold put_frame. split; [| split; [| split]].
  - eapply rw_cells_transport; [exact F8 | exact MU | exact WM | apply DJ'; cbn; lia].
  - eapply rw_cells_transport; [exact TMP | exact MU | exact WM | rewrite SZ; apply DJ'; cbn; lia].
  - exact SZ.
  - eapply rw_cells_transport; [exact PP | exact MU | exact WM | apply DJ'; cbn; lia].
